/**
 * Worker boot. Registers gantry::* on the engine, then injects this
 * connection's trigger() as forwardTrigger so middleware can replay a
 * call after the policy checks. forwardTrigger is required: there is no
 * fail-open default that would skip the governed listener.
 */
import { registerWorker } from 'iii-sdk';

import { formatFor, FUNCTION_FORMATS } from './formats.js';
import {
  onFunctionRegistration,
  onTriggerRegistration,
  onTriggerTypeRegistration,
} from './registration-hooks.js';
import { createGantryRuntime } from './runtime.js';
import { createVerdictEmitter } from './verdict-events.js';

const HANDLERS = {
  'gantry::middleware': null,
  'gantry::verify': null,
  'gantry::on-function-registration': onFunctionRegistration,
  'gantry::on-trigger-registration': onTriggerRegistration,
  'gantry::on-trigger-type-registration': onTriggerTypeRegistration,
};

function opengantryWorkerOptions() {
  return {
    workerName: 'opengantry',
    workerDescription: 'OpenGantry governance (verify, middleware, RBAC hooks)',
    otel: { enabled: process.env.OTEL_ENABLED === 'true' },
  };
}

async function startWorker() {
  const url = process.env.III_URL ?? process.env.III_ENGINE_URL ?? 'ws://127.0.0.1:49134';

  const worker = registerWorker(url, opengantryWorkerOptions());
  const verdictEmitter = createVerdictEmitter({
    trigger: (request) => worker.trigger(request),
  });
  const { middleware, verify } = createGantryRuntime({
    forwardTrigger: (function_id, payload) => worker.trigger({ function_id, payload }),
    emitVerdict: verdictEmitter.emit.bind(verdictEmitter),
  });
  HANDLERS['gantry::middleware'] = middleware;
  HANDLERS['gantry::verify'] = verify;

  for (const [functionId, formats] of Object.entries(FUNCTION_FORMATS)) {
    worker.registerFunction(functionId, HANDLERS[functionId], {
      ...(formats.description ? { description: formats.description } : {}),
      request_format: formatFor(formats.request),
      response_format: formatFor(formats.response),
    });
  }

  worker.registerTriggerType(
    {
      id: 'gantry::verdict',
      description: 'Emitted when gantry verify completes',
    },
    verdictEmitter.handler,
  );

  console.log(`opengantry worker registered (verify, middleware, RBAC hooks) → ${url}`);
}

startWorker().catch((err) => {
  console.error(err);
  process.exit(1);
});
/**
 * Zod schemas compiled to JSON Schema for registerFunction. The iii
 * contract requires request_format and response_format on every
 * registration. Payload/context .passthrough() extra adopter fields
 * (branch, tokens, custom context). The request envelope stays .strict().
 */
import { z } from 'zod';

function jsonSchema(schema) {
  const out = z.toJSONSchema(schema);
  delete out.$schema;
  return out;
}

const MiddlewarePayloadSchema = z
  .object({
    verdict_token: z.string().optional(),
    branch: z.string().optional(),
  })
  .passthrough();

const MiddlewareContextSchema = z
  .object({
    msn_id: z.string().optional(),
    holder_id: z.string().optional(),
    repo_root: z.string().optional(),
    worktree_path: z.string().optional(),
    mission_rel_path: z.string().optional(),
    mission_rel: z.string().optional(),
    verdict_token: z.string().optional(),
  })
  .passthrough();

export const MiddlewareRequestSchema = z
  .object({
    function_id: z.string(),
    payload: MiddlewarePayloadSchema.optional(),
    context: MiddlewareContextSchema.optional(),
  })
  .strict();

// The gate is a pass-through: on allow, the response is whatever the forwarded
// call returned. Typed as an open object rather than z.unknown() because
// z.toJSONSchema(z.unknown()) is `{}`, which the registry renders as "unknown"
// and `collect_worker_interface.py --assert-typed-schemas` rejects at publish.
// Same shape openwiki uses for open payloads. Widen to anyOf if a governed
// function ever returns a bare scalar or array.
export const MiddlewareResponseSchema = z.record(z.string(), z.unknown());

export const VerifyRequestSchema = z
  .object({
    repo_root: z.string(),
    msn_id: z.string().optional(),
    mission_rel_path: z.string().optional(),
    options: z.record(z.string(), z.unknown()).optional(),
  })
  .strict();

const VerifyFindingSchema = z
  .object({
    failed_gate: z.string().optional(),
    offending_file: z.string().optional(),
    line: z.number().optional(),
    severity: z.string().optional(),
    resolution_hint: z.string().optional(),
  })
  .strict();

export const VerifyResponseSchema = z
  .object({
    status: z.string(),
    phase: z.string().optional(),
    message: z.string().optional(),
    error_code: z.string().optional(),
    exit_code: z.number().optional(),
    msn_id: z.string().optional(),
    mission_file_path: z.string().optional(),
    findings: z.array(VerifyFindingSchema).optional(),
    fix_hints: z.array(z.string()).optional(),
    next_actions: z.array(z.string()).optional(),
  })
  .strict();

export const FunctionIdEnvelopeSchema = z
  .object({
    function_id: z.string(),
  })
  .strict();

export const OnTriggerTypeRegistrationRequestSchema = z
  .object({
    type_id: z.string(),
  })
  .strict();

// onTriggerTypeRegistration is an unconditional deny — it always throws
// GantryDenied and has no success shape. Declared as the empty strict object so
// the schema stays typed (see the note on MiddlewareResponseSchema).
export const OnTriggerTypeRegistrationResponseSchema = z.object({}).strict();

export const FUNCTION_FORMATS = {
  'gantry::middleware': {
    request: MiddlewareRequestSchema,
    response: MiddlewareResponseSchema,
  },
  'gantry::verify': {
    description:
      "Verify a mission by running the repo's own build and test gates. Returns a signed verdict token bound to that mission revision, which promote-class calls must carry.",
    request: VerifyRequestSchema,
    response: VerifyResponseSchema,
  },
  'gantry::on-function-registration': {
    request: FunctionIdEnvelopeSchema,
    response: FunctionIdEnvelopeSchema,
  },
  'gantry::on-trigger-registration': {
    request: FunctionIdEnvelopeSchema,
    response: FunctionIdEnvelopeSchema,
  },
  'gantry::on-trigger-type-registration': {
    request: OnTriggerTypeRegistrationRequestSchema,
    response: OnTriggerTypeRegistrationResponseSchema,
  },
};

export function formatFor(schema) {
  return jsonSchema(schema);
}
