/**


/** Thrown when verify coalescer is at maxInFlight capacity. */
export class VerifyCoalescerSaturationError extends Error {
  constructor() {
    super('verify queue saturated');
    this.name = 'VerifyCoalescerSaturationError';
    this.code = 'GXT_VERIFY_SATURATED';
  }
}

/** Single-flight verify coalescing keyed by caller-supplied cache key. */
export class VerifyCoalescer {
  constructor() {
    this.inFlight = new Map();
    this.maxInFlight = 32;
  }

  async run(key, fn) {
    if (this.inFlight.has(key)) {
      return this.inFlight.get(key);
    }
    if (this.inFlight.size >= this.maxInFlight) {
      throw new VerifyCoalescerSaturationError();
    }
    const promise = fn().finally(() => {
      this.inFlight.delete(key);
    });
    this.inFlight.set(key, promise);
    return promise;
  }
}

function verifyFailedPayload(code, hint) {
  return {
    status: 'failed',
    error_code: code,
    findings: [
      {
        failed_gate: 'gate',
        resolution_hint: hint,
      },
    ],
  };
8:The proof is the repo's own gates: the build and test commands that already exist, plus a declared edit scope. Pass them and you get a signed verdict token bound to that exact mission revision. Edit the work order afterwards and the token stops matching.
12:This worker is the hot path only. It runs OpenGantry kernel `verifyMission` and gates promote-class calls on a governed listener. It does not admit sessions (`session::auth` is your IdP), hold for a human (`approval-gate`), or push git. It never writes `.gitagent/` law. Planner commits missions on the host.
