export async function runVerify(data) {
  const repoRoot = resolveVerifyRepoRoot(data.repo_root);
  return verifyMission({
    repoRoot,
    missionRelPath: data.mission_rel_path,
    options: { skipStaleEvidence: true, ...data.options },
  });
}

async function emitVerdictForResult(deps, data, result) {
  try {
    await deps.emitVerdict({
      status: result?.status ?? 'failed',
      error_code: result?.error_code ?? null,
      repo_root: data?.repo_root ?? null,
      msn_id: data?.msn_id ?? result?.msn_id ?? null,
      mission_rel_path: data?.mission_rel_path ?? result?.mission_file_path ?? null,
    });
  } catch {
    /* verify result is authoritative; fan-out is best-effort */
  }
}

export function createVerifyHandler(deps) {
  return async function gantryVerify(data) {
    const repoRoot = data?.repo_root;
    const key = JSON.stringify({
      repo_root: repoRoot ?? '',
      msn_id: data?.msn_id ?? '',
      mission_rel_path: data?.mission_rel_path ?? '',
      options: data?.options ?? null,
    });
    let result;
    try {
      result = await deps.coalescer.run(key, () => runVerify(data));
    } catch (e) {
      // Return a failed payload so the agent can retry. Throwing would look
      // like a worker crash rather than a full verify queue.
      if (e instanceof VerifyCoalescerSaturationError) {
        const saturated = verifyFailedPayload(
          'GXT_VERIFY_SATURATED',
          'verify queue saturated; retry later',
        );
        await emitVerdictForResult(deps, data, saturated);
        return saturated;
      }
      throw e;
    }
    if (result?.status === 'passed' && data?.msn_id && data?.mission_rel_path && repoRoot) {
      try {
        await onVerifyPassed(deps, data);
      } catch (e) {
        const hint =
          e instanceof GantryDenied ? e.hint : e instanceof Error ? e.message : String(e);
        const bindFailed = verifyFailedPayload(
          'GXT_VERIFY_BIND_FAILED',
          `verdict scope bind failed: ${hint}`,
        );
        await emitVerdictForResult(deps, data, bindFailed);
        return bindFailed;
      }
After every `gantry::verify` completes (pass or fail), the worker fans out a best-effort event to every binding on the `gantry::verdict` trigger type:

```json
{
  "status": "passed",
  "error_code": null,
  "repo_root": "/path/to/repo",
  "msn_id": "MSN-0001",
  "mission_rel_path": ".gitagent/missions/MSN-0001.yaml"
}
```

Subscribe a sibling function (audit log, Slack notifier, console inbox) via `registerTrigger` on `gantry::verdict`. A failing subscriber never fails verify.

## Quickstart

From zero to a fail-closed land on the governed port:

```bash
iii trigger compose::add worker=opengantry worker=approval-gate worker=worktree worker=ide
iii   # starts the engine + workers
```

Add the governed listener block from [Recommended stack](#recommended-stack) to `~/.iii/config.yaml`, restart `iii`, then run the canonical pipeline:

```js
import { registerWorker } from 'iii-sdk';

const iii = registerWorker('ws://127.0.0.1:49135', { workerName: 'demo' });

// 1. Mint an isolated worktree for the agent.
const wt = await iii.trigger({
  function_id: 'worktree::create',
  payload: { repo_root: '/path/to/repo', branch: 'gxt/msn-0001' },
});

// 2. Agent works in wt.path, then verify the active mission.
const verify = await iii.trigger({
  function_id: 'gantry::verify',
  payload: {
    repo_root: '/path/to/repo',
    msn_id: 'MSN-0001',
    mission_rel_path: '.gitagent/missions/MSN-0001.yaml',
  },
});

// 3. Land with the verdict token (promote-class — middleware gates this).
const land = await iii.trigger({
  function_id: 'worktree::land',
  payload: { worktree_id: wt.id },
  context: {
    msn_id: 'MSN-0001',
    worktree_path: '/path/to/repo',
    verdict_token: verify.verdict_token,
  },
});
```

Without a verdict token from `gantry::verify`, middleware throws `GantryDenied` (fail-closed).

Initialize OpenGantry in the repo you want governed (`gantry init`), run `gantry::verify` for the active mission, then retry the land call with the verdict token in `context` or `payload`.

A sandboxed Compose worker only mounts its own folder. `gantry::verify` against a host repo needs a host-started worker that can see that absolute path.

## Configuration

  workers:
    configuration: {}
    iii-worker-manager:
      host: 127.0.0.1
      port: 49160
    # The governed listener. `gantry::middleware` sees every call that arrives
    # here, and refuses a promote-class call (::merge, ::push, ::deploy, ...)
    # that carries no verdict token for the mission on disk.
    iii-worker-manager#governed:
      host: 127.0.0.1
      port: 49161
      middleware_function_id: gantry::middleware
    iii-sandbox:
      auto_install: true
      image_allowlist: [python, node]
      default_idle_timeout_secs: 300
      max_concurrent_sandboxes: 8
      default_cpus: 1

